_CLAUSE_RE = re.compile(
    r"^\s*(?P<key>[\w.]+)\s+(?P<op>>=|<=|!=|=|<|>|LIKE|ILIKE|IN)\s+(?P<val>.+?)\s*$",
    re.IGNORECASE,
)


def _parse_filter_string(filter_string: str | None) -> list[_FilterClause]:
    if not filter_string or not filter_string.strip():
        return []
    clauses: list[_FilterClause] = []
    for part in re.split(r"\s+AND\s+", filter_string.strip(), flags=re.IGNORECASE):
        part = part.strip()
        if not part:
            continue
        m = _CLAUSE_RE.match(part)
        if not m:
            raise MlflowException(
                f"Invalid filter clause: {part!r}", error_code=INVALID_PARAMETER_VALUE
            )
        clauses.append(
            _FilterClause(
                key=m.group("key"),
                op=m.group("op").upper(),
                value=_parse_value(m.group("val")),
            )
        )
    return clauses


def _like_to_regex(pattern: str) -> str:
    out = []
    for ch in pattern:
        if ch == "%":
            out.append(".*")
        elif ch == "_":
            out.append(".")
        else:
            out.append(re.escape(ch))
    return "^" + "".join(out) + "$"


def _compare_numeric(actual: Any, op: str, expected: Any) -> bool:
    if op == "=":
        return actual == expected
    if op == "!=":
        return actual != expected
    if op == ">":
        return actual > expected
    if op == "<":
        return actual < expected
    if op == ">=":
        return actual >= expected
    if op == "<=":
        return actual <= expected
    raise MlflowException(
        f"Invalid operator {op!r} for numeric comparison", error_code=INVALID_PARAMETER_VALUE
    )


